@pytest.mark.parametrize("input_layout", ["contiguous", "transpose", "strided"]) @pytest.mark.parametrize("mask_layout", ["contiguous", "transpose", "strided"]) @pytest.mark.parametrize("grad_layout", ["contiguous", "strided"]) @pytest.mark.parametrize("dim", [0, 1]) def test_independent_tensor_strides(input_layout, mask_layout, grad_layout, dim, device): values = torch.arange(32, device=device, dtype=torch.float32).reshape(4, 8) / 32 mask_values = torch.arange(32, device=device).reshape(4, 8) % 3 == 0 input = _with_layout(values, input_layout).detach().requires_grad_() mask = _with_layout(mask_values, mask_layout) upstream = _with_layout(values.flip(1), grad_layout) ref_input = values.clone().requires_grad_() snapshots = [t.detach().clone() for t in (input, mask, upstream)] actual = trident.function.masked_softmax(input, mask, dim) expected = masked_softmax(ref_input, mask_values, dim) actual.backward(upstream) expected.backward(upstream) > torch.testing.assert_close(actual, expected, rtol=1e-6, atol=1e-7) E AssertionError: Tensor-likes are not close! E E Mismatched elements: 20 / 32 (62.5%) E Greatest absolute difference: 0.34595420956611633 at index (2, 1) (up to 1e-07 allowed) E Greatest relative difference: inf at index (1, 1) (up to 1e-06 allowed)
